def solution(bandage, health, attacks):
    time_to_heal, heal_per_second, additional_heal = bandage
    max_health = health
    current_health = health

    attack_index = 0
    consecutive_time = 0

    for second in range(1, time_to_heal + 1):
        if attack_index < len(attacks) and attacks[attack_index][0] == second:
            damage = attacks[attack_index][1]
            current_health -= damage
            attack_index += 1

            if current_health <= 0:
                return -1

        if current_health < max_health:
            current_health += heal_per_second
            consecutive_time += 1

            if consecutive_time >= time_to_heal:
                current_health += additional_heal
        else:
            consecutive_time = 0

    while attack_index < len(attacks):
        _, damage = attacks[attack_index]
        current_health -= damage
        attack_index += 1

        if current_health <= 0:
            return -1

    return current_health if current_health > 0 else -1

