def solution(storage, requests):
    from collections import deque

    grid = [list(s) for s in storage]
    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def bfs(start_row, start_col, target):
        queue = deque([(start_row, start_col)])
        visited = set()
        visited.add((start_row, start_col))
        removed_containers = []

        while queue:
            row, col = queue.popleft()

            if grid[row][col] == target:
                removed_containers.append((row, col))

                for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    new_r, new_c = row + dr, col + dc
                    if is_valid(new_r, new_c) and (new_r, new_c) not in visited and grid[new_r][new_c] != '.':
                        queue.append((new_r, new_c))
                        visited.add((new_r, new_c))

        return removed_containers

    def remove_containers(containers):
        for r, c in containers:
            grid[r][c] = '.'

    for request in requests:
        if len(request) == 1:
            for i in range(rows):
                for j in range(cols):
                    if grid[i][j] == request:
                        remove_containers(bfs(i, j, request))
        else:
            target = request[0]
            count = int(request[1:])
            for _ in range(count):
                found = False
                for i in range(rows):
                    for j in range(cols):
                        if grid[i][j] == target:
                            remove_containers(bfs(i, j, target))
                            found = True
                            break
                    if found:
                        break

    remaining_containers = sum(row.count('.') for row in grid)
    return remaining_containers

