def solution(edges):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    def dfs(node, visited):
        visited.add(node)
        count = 1
        for neighbor in graph[node]:
            if neighbor not in visited:
                count += dfs(neighbor, visited)
        return count

    nodes = set(range(len(graph)))
    visited = set()

    doughnut_count = 0
    stick_count = 0
    octagon_count = 0

    for node in nodes:
        if node not in visited:
            size = dfs(node, visited)
            if size > 1:
                doughnut_count += 1
            elif size == 1:
                stick_count += 1
            else:
                octagon_count += 1

    return [len(nodes) + 1] + [doughnut_count, stick_count, octagon_count] if octagon_count == 1 else []
